import sys
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from time import time
from typing import Dict, List, Optional

def fetch_package_version(name: str) -> str:
    url = f"https://pypi.org/pypi/{name}/json"
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
        if "info" in data and isinstance(data["info"], dict) and "version" in data["info"]:
            return data["info"]["version"]
        return "ERROR"
    except (requests.RequestException, ValueError):
        return "ERROR"

def process_package(name: str, results: Dict[str, str], last_request_time: float, in_flight: int) -> None:
    if in_flight >= 4:
        return
    version = fetch_package_version(name)
    results[name] = version
    in_flight += 1
    last_request_time = time()
    while in_flight >= 4 and time() - last_request_time < 1:
        time.sleep(0.001)

def main():
    package_names = [line.strip() for line in sys.stdin if line.strip()]
    results = {}
    last_request_time = 0
    in_flight = 0

    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = []
        for name in package_names:
            future = executor.submit(process_package, name, results, last_request_time, in_flight)
            futures.append(future)

        for future in as_completed(futures):
            name = package_names[next(i for i, n in enumerate(package_names) if n == future._result_key)]
            results[name] = future.result()

    for name in package_names:
        print(f"{name}\t{results[name]}")

if __name__ == "__main__":
    main()
